result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-debounce/test/debounce.test.js", "content": "import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import debounce from '../src/debounce.js';

describe('debounce', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('preserves multiple arguments and this binding (regression: original bug)', () => {
    const calls = [];
    const obj = {
      name: 'widget',
      record(a, b) {
        // Assert what the callee actually receives.
        expect(this).toBe(obj);
        calls.push([a, b]);
      },
    };

    obj.debounced = debounce(obj.record, 100);

    const result = obj.debounced(1, 2);
    vi.advanceTimersByTime(99);
    expect(calls).toEqual([]);
    vi.advanceTimersByTime(1);

    expect(calls).toEqual([[1, 2]]);
    expect(result).toBeUndefined(); // debounced returns nothing by design
  });

  it('collapses bursts into a single trailing call', () => {
    const fn = vi.fn();
    const d = debounce(fn, 50);
    d('a', 'b');
    vi.advanceTimersByTime(10);
    d('c', 'd');
    vi.advanceTimersByTime(60);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith('c', 'd');
  });

  it('cancel prevents a pending invocation', () => {
    const fn = vi.fn();
    const d = debounce(fn, 100);
    d('x');
    vi.advanceTimersByTime(50);
    d.cancel();
    vi.advanceTimersByTime(200);
    expect(fn).not.toHaveBeenCalled();

    // Still usable after cancel.
    d('y');
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith('y');
  });
});
"})
print(result)

